('collaborate.s001', 'collaborate', '协作与联系', '栏目一', 'Channel 01', '栏目一', 'Channel 01', '0', 548),
('collaborate.s002', 'collaborate', '协作与联系', '学术协作申请', 'Academic Collaboration Application', '学术协作申请', 'Academic Collaboration Application', '0', 549),
('collaborate.s003', 'collaborate', '协作与联系', '诚邀全球学者与机构开展对等学术合作，ACTION 国际顾问委员会与执行团队将对合作申请进行评估对接，合作范围涵盖针刺报告规范、实施科学研究、国际联合临床试验、学术交流推广等方向。', 'We sincerely invite scholars and institutions worldwide for equal academic partnerships. The ACTION International Advisory Committee and Executive Team will review and follow up on applications. Potential cooperation covers acupuncture reporting guidelines, implementation science research, international joint clinical trials, and academic exchange.', '诚邀全球学者与机构开展对等学术合作，ACTION 国际顾问委员会与执行团队将对合作申请进行评估对接，合作范围涵盖针刺报告规范、实施科学研究、国际联合临床试验、学术交流推广等方向。', 'We sincerely invite scholars and institutions worldwide for equal academic partnerships. The ACTION International Advisory Committee and Executive Team will review and follow up on applications. Potential cooperation covers acupuncture reporting guidelines, implementation science research, international joint clinical trials, and academic exchange.', '0', 550),
('collaborate.s004', 'collaborate', '协作与联系', '可合作方向', 'Areas of collaboration', '可合作方向', 'Areas of collaboration', '0', 551),
('collaborate.s005', 'collaborate', '协作与联系', '针刺报告规范共建', 'Co-development of Acupuncture Reporting Guidelines', '针刺报告规范共建', 'Co-development of Acupuncture Reporting Guidelines', '0', 552),
('collaborate.s006', 'collaborate', '协作与联系', '开展针刺相关报告指南开发、条目修订、本土化推广等工作。', 'Develop, revise and locally adapt reporting standards for acupuncture research.', '开展针刺相关报告指南开发、条目修订、本土化推广等工作。', 'Develop, revise and locally adapt reporting standards for acupuncture research.', '0', 553),
('collaborate.s007', 'collaborate', '协作与联系', '针刺临床研究合作', 'Joint Acupuncture Clinical Research Projects', '针刺临床研究合作', 'Joint Acupuncture Clinical Research Projects', '0', 554),
('collaborate.s008', 'collaborate', '协作与联系', '洽谈多中心针刺临床试验、真实世界研究、系统综述等针刺临床研究项目。', 'Negotiate multi-centre acupuncture trials, real-world studies, systematic reviews and other joint research programmes.', '洽谈多中心针刺临床试验、真实世界研究、系统综述等针刺临床研究项目。', 'Negotiate multi-centre acupuncture trials, real-world studies, systematic reviews and other joint research programmes.', '0', 555),
('collaborate.s009', 'collaborate', '协作与联系', '实施科学转化研究合作', 'Collaboration on Implementation Science Transformation Research', '实施科学转化研究合作', 'Collaboration on Implementation Science Transformation Research', '0', 556),
